 export function parseDuration(text) {
-  throw new Error('not implemented');
+  if (typeof text !== 'string') {
+    throw new TypeError('Input must be a string');
+  }
+
+  // Handle bare number (no unit) - it's seconds
+  // Also handle cases like "1h30m" where there's no whitespace between parts
+  // We need to split on unit boundaries as well
+  
+  let totalSeconds = 0;
+  const seenUnits = new Set();
+
+  // First, check for empty string
+  if (text === '') {
+    throw new RangeError('Empty string');
+  }
+
+  // Split on boundaries: between a digit and a unit, or between a unit and a digit
+  // Also split on whitespace
+  const parts = text.split(/(?<=[0-9])(?=[hms])|(?<=[hms])(?=[0-9])/).filter(Boolean);
+
+  for (const part of parts) {
+    // Try to match a number followed by a unit
+    const match = part.match(/^(-?\d+)([hms])$/);
+    if (!match) {
+      throw new RangeError(`Invalid part: ${part}`);
+    }
+
+    const value = parseInt(match[1], 10);
+    const unit = match[2];
+
+    // Check for negative or fractional
+    if (value < 0 || value % 1 !== 0) {
+      throw new RangeError(`Negative or fractional number: ${part}`);
+    }
+
+    if (seenUnits.has(unit)) {
+      throw new RangeError(`Repeated unit: ${unit}`);
+    }
+    seenUnits.add(unit);
+
+    if (unit === 'h') {
+      totalSeconds += value * 3600;
+    } else if (unit === 'm') {
+      totalSeconds += value * 60;
+    } else if (unit === 's') {
+      totalSeconds += value;
+    }
+  }
+
+  return totalSeconds;
 }

